"""Что колонка имеет право произнести.

Модуль отвечает на один вопрос: что делать с ответом языковой модели, когда
модель ошиблась. Не «как её настроить», а как не дать колонке сказать ерунду.

Повод. Замеры этой колонки за один день дали полный набор отказов, и все они
пришли из одного места - из ответа модели:

    кто ты                     -> "Я ИИ, созданный Alibaba Cloud"
    спокойной ночи             -> "Night to you! ... полон смычка"
    что сейчас погода          -> "实时天气信息"
    спасибо, а что погода      -> "не имею доступа к погоде"

Общий у них признак: модель не умеет сказать «не знаю» и не знает, на каком
языке с ней разговаривают. Предположение, что большая модель - это плавная
деградация, неверно: это генератор без состояния «не знаю» и без проверки
языка. Поэтому выход модели проверяется, а не доверяется.

Четыре фильтра:
  1. Иероглифы в русском ответе - не проходит никогда.
  2. Ответ не на том языке: латиница вместо кириллицы.
  3. Отказ от того, что колонка умеет, - враньё про себя.
  4. Колонка называет себя чужой разработкой - тоже враньё про себя.

Проверки: python3 vendor/irene-va/jane_guard.py
"""

import re
import unicodedata

# Иероглифы: в русском ответе их быть не может в принципе.
_HAN = re.compile(r"[\u3400-\u4dbf\u4e00-\u9fff\uf900-\ufaff]")

# Чужие разработки, которыми колонка себя называла.
_VENDOR = re.compile(
    r"\b(?:alibaba|alipay|openai|chat\s*gpt|gpt-?[\dv]|claude|gemini|"
    r"qwen[\dv.-]*|deepseek|llama|mistral|vicuna|gemma|phi-?[\dv]|"
    r"anthropic|copilot|microsoft\s+bing|siri|cortana|google\s+assistant|"
    r"амазон|яндекс\s+станция)\b", re.I)

# Латинские слова ПОДРЯД, два и больше. Не всякая латиница - утечка: «это
# группа Radiohead» или «напиши в Telegram» уместны, и отличить название от
# чужого предложения по словарю нельзя. А вот два английских слова подряд
# внутри русской фразы - это уже не название, это модель заговорила по-
# английски посреди предложения. Именно так выглядел настоящий отказ:
# «... Adams Channel Network Access Internet ...» внутри ответа про 1999 год.
_LAT_RUN = re.compile(r"[A-Za-z]{3,}(?:\s+[A-Za-z]{3,})+")

# Обрыв на полуслове: ответ есть, а знака конца нет.
_TAIL_OK = re.compile(r"[.!?…»\"')\]]\s*$")

# Отказ от того, что есть. Проверяем именно отказ, а не любое упоминание.
_DENY = re.compile(
    r"(?:не\s+имею|нет\s+доступа|не\s+получить|не\s+могу|не\s+в\s+состоянии)"
    r"[\s\S]{0,40}?"
    r"(?:прогноз|погод|времен|дат|будильник|напоминан|музык|песн|дому|"
    r"устройств|часы)",
    re.I)

# Отсылка к человеку, которого нет. У локальной колонки нет оператора, и
# «обратитесь к оператору связи» - это отказ, поданный вежливо.
_DEFL = re.compile(
    r"\b(?:обратит[её]сь|обращайтесь|свяжитесь|напишите\s+в|позвоните)\s+"
    r"(?:в|на|к)?\s*(?:оператор|поддержк|служб|сервис|сервер|админ)",
    re.I)

# Отказ без всякой причины. Модель на 0.5b параметров перестрахована и
# отказывает там, где отказывать нечего: рецепт, анекдот, совет. У локальной
# колонки нет политики контента, и отказ здесь просто бессмысленен.
_REFUSE = re.compile(
    r"\b(?:не\s+участвую|не\s+буду\s+участвовать|я\s+отказываюсь|"
    r"это\s+выходит\s+за\s+рамки)\b"
    # Отказ без причины пишется десятком способов, и перечисление глаголов
    # здесь осознанное: модель на 0.5b параметров отказывает по форме, а не по
    # смыслу. Пойманная причина важнее любого одного глагола.
    r"|не\s+могу\s+(?:помочь|созда|создава|создать|написать|рассказ\w*|"
    r"придум\w*|показать|поделиться|выполн\w*|запомн\w*|поискать|ответить|"
    r"найти|разрешить|оценить|оценивать)"
    r"|(?:не\s+)?способен\s+(?:вам|это|делать|помочь)",
    re.I)

# Ответ, в котором нет ответа. «Конечно! Как я могу помочь вам сегодня?»
# - вежливая пустота: человека убедили, что его услышали, и ничего не сказали.
# Для колонки такая фраза хуже честного «не знаю», потому что она маскирует
# незнание под участие в разговоре.
_COURTESY = re.compile(
    r"^\s*(?:конечно|хорошо|отлично|прекрасно|понял[аи]?|понятно|ясно|"
    r"ок|ага|угу)\b[\s,.:;!?\-]*", re.I)

_FILLER_CORE = re.compile(
    r"(?:как\s+(?:я\s+)?(?:могу|можно)\s+(?:вам\s+|тебе\s+)?"
    r"(?:помочь|дать\s+совет|помочь\s+вам)|"
    r"чем\s+(?:я\s+)?(?:могу|можно)\s+помочь|"
    r"что\s+(?:бы\s+)?вы\s+(?:хотите|желаете|нужно)|"
    r"какие\s+(?:у\s+вас\s+)?(?:есть\s+)?вопросы|"
    r"дайте\s+(?:мне\s+)?подробности|"
    r"уточните(?:,\s*)?|"
    r"на\s+какую\s+тему)", re.I)


def _is_filler(t):
    """Вежливая пустота: внутри ответа не остаётся ничего содержательного.

    Считаются слова после вежливости и после ключевой фразы. Считать надо,
    а не подгонять регулярку под примеры: «как я могу помочь вам сегодня»
    и «как я могу помочь вам включить свет» отличаются только длиной хвоста,
    и ни одна регулярка без счёта их не различит.
    """
    rest = _COURTESY.sub("", t, count=1)
    m = _FILLER_CORE.search(rest)
    if not m:
        return False
    tail = (rest[:m.start()] + rest[m.end():])
    return len(re.findall(r"[\w\-]+", tail, re.UNICODE)) < 3


_CYR = re.compile(r"[\u0400-\u04ff]")
_LAT = re.compile(r"[A-Za-z]")
_WORD = re.compile(r"[^\W\d_]+", re.U)

# Абстиненция - короткая, без извинений за колонку.
#
# Для большинства причин подходит короткое «не поняла». Но когда модель
# отказалась или выдала вежливую пустоту, полезнее сказать, что колонка
# вообще умеет: человек после отказа обычно спрашивает «а ты что можешь?»,
# и это лишний круг. Отказ с подсказкой короче.
_PHRASES = (
    "Не поняла.",
    "Не поняла. Повторите иначе.",
    "Пока не поняла.",
    "Это я не поняла. Скажите проще.",
)

_HINT = ("Я не поняла, о чём речь. Зато я умею: говорить время и дату, "
         "читать погоду, ставить будильники и напоминания, "
         "включать свет и ставить музыку.")

# Причины, после которых уместна подсказка вместо молчаливого отказа.
_HINT_REASONS = frozenset((
    "отказ без причины", "отказ от того, что умеем", "вежливая пустота",
))


def _letters(text):
    return len(_CYR.findall(text)) + len(_LAT.findall(text))


def reason_to_reject(text):
    """Почему ответ нельзя произнести. None - можно."""
    if text is None:
        return "пусто"
    t = str(text).strip()
    if not t:
        return "пусто"

    # Ответ без ответа проверяем раньше всего: он выглядит вежливым, и
    # именно поэтому его легче всего пропустить.
    if _is_filler(t):
        return "вежливая пустота"

    # Проверка 1: иероглифы.
    if _HAN.search(t):
        return "иероглифы"

# Проверка 3 и 4: враньё про себя.
    if _VENDOR.search(t):
        return "чужая разработка"
    if _DENY.search(t):
        return "отказ от того, что умеем"
    if _DEFL.search(t):
        return "отсылка к оператору"
    if _REFUSE.search(t):
        return "отказ без причины"

    # Проверка 2: ответ не на русском. Сначала - на чём он начинается.
    # «Night to you! У меня сейчас спокойный и полон смычка» содержит
    # латиницы меньше, чем кириллицы, и потому проходит сравнение по
    # количеству, хотя ответ начинается на чужом языке.
    words = _WORD.findall(t)
    if words:
        first = words[0]
        if _LAT.search(first) and not _CYR.search(first):
            return "ответ не на русском"

    # Дальше - по количеству: латиница прощается, если кириллицы заметно
    # больше. Названия и термины встречаются, и это нормально.
    cyr = len(_CYR.findall(t))
    lat = len(_LAT.findall(t))
    if cyr + lat > 0 and lat > cyr:
        return "ответ не на русском"

# Мусор из обрезанного слова: неразрывный кусок кириллицы длиннее
    # половины фразы означает, что фраза пришла обрезанной.
    if words:
        longest = max(len(w) for w in words)
        if longest > 24 and longest > 0.5 * len(t):
            return "обрезанное слово"

    # Латиница внутри русской фразы. Проверяется ДО обрыва, чтобы в журнале
    # лежала настоящая причина, а не общий признак «нет конца фразы».
    if cyr >= 8 and _LAT_RUN.search(t):
        return "латиница внутри ответа"

    # Обрыв на полуслове. Два случая:
    #   длинный ответ без знака конца - почти всегда обрыв;
    #   короткий ответ, у которого последнее слово короткое и конца нет:
    #   «Вот как можн». Короткие ответы раньше не проверялись вовсе, и обрыв
    #   в них проходил незамеченным.
    if not _TAIL_OK.search(t):
        if len(t) > 40:
            return "обрыв на полуслове"
        if len(words) >= 3 and len(words[-1]) <= 4:
            return "обрыв на полуслове"

    return None


def ok(text):
    return reason_to_reject(text) is None


def abstain(text):
    """Ответ или отказ. Никогда не пусто, никогда не с извинениями."""
    why = reason_to_reject(text)
    if why is None:
        return str(text).strip()
    if why in _HINT_REASONS:
        return _HINT
    # Выбор фразы зависит от текста запроса-отказа, а не от времени, чтобы
    # два одинаковых отказа подряд не звучали одинаково.
    idx = sum(ord(c) for c in str(text)[:40]) % len(_PHRASES)
    return _PHRASES[idx]


# ---------------------------------------------------------------------------
# Проверки
# ---------------------------------------------------------------------------
def selfcheck():
    fails = []

    def want(cond, msg):
        if not cond:
            fails.append(msg)

    # Реальные ответы этой колонки. Ни один не должен пройти.
    bad_real = (
        "Извините, но как искусственный интеллект, я не имею доступа к实时天气信息。",
        "Night to you! У меня сейчас спокойный и полон смычка.",
        "Я искусственный интеллект, созданный Alibaba Cloud.",
        "Пожалуйста, обратитесь к оператору связи.",
        # Отказ на дату: вопрос уходил в модель из-за дыры в маршруте, а
        # модель отвечала отказом. Регулярка это пропускала, потому что ждала
        # «не имею доступа к дате», а пришло «не могу давать информацию о
        # текущей дате».
        "Я не могу давать информацию о текущей дате или времени, так как у меня нет доступа к интернету.",
        "Я не участвую в создании или распространении контента.",
        # Отказ на рецепт. Модель отказывала по форме, и каждый следующий
        # отказ приходил с новым глаголом: сначала «не участвую», потом
        # «не могу создавать». Перечисление глаголов - сознательная плата за
        # модель на 0.5b.
        "Извините, но я не могу создавать или рекомендовать конкретные рецепты.",
        "Конечно! Вот увлекательный анекдот: \"Извините, но я не могу помочь с этим.\"",
        # Живые ответы этой колонки, снятые при разведке утечек.
        "Извините, но я, Qwen, не является человеком и не способен говорить с людьми",
        "В 1999 году произошли некоторые изменения в мире искусственного Adams Channel Network Access Internet сообщества.",
        "Конечно, я могу помочь вам сделать это. Вот как можн",
        "Как искусственный интеллект, я не способен вам предл",
    )
    for t in bad_real:
        want(not ok(t), "пропущен мусор: %r" % t[:44])

    # Причина должна быть названа, иначе непонятно, что чинить.
    want(reason_to_reject(bad_real[0]) == "иероглифы", "причина: иероглифы")
    want(reason_to_reject("Night to you! У меня полон смычка") == "ответ не на русском",
         "причина: не на русском")
    want(reason_to_reject("создан Alibaba Cloud") == "чужая разработка",
         "причина: чужая разработка")
    want(reason_to_reject("я не имею доступа к погоде") == "отказ от того, что умеем",
         "причина: отказ")
    want(reason_to_reject("обратитесь к оператору связи") == "отсылка к оператору",
         "причина: отсылка к оператору")
    want(reason_to_reject("не могу давать информацию о дате") == "отказ от того, что умеем",
         "причина: отказ про дату")
    want(reason_to_reject("не участвую в создании контента") == "отказ без причины",
         "причина: отказ про контент")
    want(reason_to_reject("я не могу создавать рецепты") == "отказ без причины",
         "причина: отказ на рецепт")
    want(reason_to_reject("я, Qwen, не человек") == "чужая разработка",
         "причина: модель назвала себя")
    want(reason_to_reject("в мире искусственного Adams Channel Network сообщества")
         == "латиница внутри ответа",
         "причина: латиница внутри ответа")
    want(reason_to_reject("Вот как можн") == "обрыв на полуслове",
         "причина: обрыв")

    # Нормальные ответы проходят. В том числе с латиницей внутри: названия и
    # термины это не «не тот язык».
    good = (
        "Погода сейчас солнечная, +17 градусов.",
        "Сейчас 14:32, вторник, 5 октября 2026 года.",
        "Напомню через час: купить хлеб.",
        "Это группа Radiohead, поет альтернативный рок.",
        "Не поняла.",
        "Сейчас 7 градусов, ветер 3 метра в секунду.",
        "Это группа Radiohead, поет альтернативный рок.",
        "Напиши это в Telegram, там длиннее.",
    )
    for t in good:
        want(ok(t), "забран хороший ответ: %r" % t[:44])

    # Отказ всегда даёт осмысленную фразу и никогда не пустую. На отказе
    # и на вежливой пустоте вместо молчания идёт подсказка, что колонка
    # умеет: после отказа человек обычно спрашивает «а ты что можешь?»,
    # и это лишний круг.
    for t in bad_real + (None, "", "   "):
        got = abstain(t)
        want(got in _PHRASES or got == _HINT,
             "плохая абстиненция на %r: %r" % (t, got))
        want(len(got) > 3, "абстиненция слишком короткая")

    for t in ("Я не могу давать информацию о дате.",
              "Конечно! Как я могу помочь вам сегодня?",
              "Чем могу помочь?"):
        want(abstain(t) == _HINT, "без подсказки: %r" % t)

    # А вот языковой мусор подсказкой не сопровождается: человек говорит,
    # колонка не поняла, и перечисление умений только путает.
    want(abstain("Night to you!") in _PHRASES,
         "подсказка на языковой мусор")

# Вежливая пустота опознаётся и не проходит как ответ.
    for t in ("Конечно! Как я могу помочь вам сегодня?",
              "Чем могу помочь?",
              "Что бы вы хотите узнать?"):
        want(reason_to_reject(t) == "вежливая пустота",
             "не опознана пустота: %r" % t)

    # Граница проходит по содержанию хвоста: «уточните, пожалуйста, о чём
    # речь» - это запрос, хоть и бесполезный, и пустотой не считается.
    want(reason_to_reject("Уточните, пожалуйста, о чём речь.") != "вежливая пустота",
         "запрос на уточнение принят за пустоту")
    want(reason_to_reject("Как я могу помочь вам включить свет?")
         != "вежливая пустота",
         "полезный ответ принят за пустоту")

    # Одинаковый мусор дважды подряд не должен звучать одинаково - иначе
    # колонка выглядит сломанной.
    outs = {abstain(t) for t in bad_real}
    want(len(outs) >= 2, "все отказы звучат одинаково")

    for f in fails:
        print("FAIL  " + f)
    if not fails:
        print("ok    jane_guard: мусор не произносится, хорошие ответы проходят")
    print("ИТОГ: провалено %d" % len(fails))
    return 1 if fails else 0


if __name__ == "__main__":
    import sys
    sys.exit(selfcheck())